<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import { useContextContext } from './context-state.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet; } let { class: className = '', children, ...rest }: Props = $props(); const context = useContextContext('ContextContentFooter'); const formattedCost = $derived(/^[A-Z]{3}$/.test(context.currency) ? new Intl.NumberFormat(undefined, { style: 'currency', currency: context.currency }).format(context.cost ?? 0) : `${context.currency}${(context.cost ?? 0).toFixed(4)}`);</script>
<div {...rest} class={cn('svadmin-ai-context-part__footer', className)} data-slot="context-content-footer">{#if children}{@render children()}{:else}<span>Total cost</span><strong>{formattedCost}</strong>{/if}</div>
